-- Relational table layout from Bảng CSDL.docx. Legacy identifiers and payloads
-- remain lossless in private compatibility storage; existing RPC contracts stay stable.
-- Passwords remain exclusively in Supabase Auth. Unknown historical values stay NULL.
-- Runtime writes use the existing authorized RPCs and transactionally maintain these tables.
lock table public.leads,public.lead_assignments,public.lead_activities,public.lead_appointments,
 public.lead_closure_reviews,public.lead_notifications,public.lead_audit_logs,
 public.lead_receptions,public.lead_attachments,public.lead_care_rounds in access exclusive mode;

-- OID-based foreign keys, grants and RLS policies survive these moves.
do $$ declare n text; f record; definition text; begin
 foreach n in array array['leads','lead_assignments','lead_activities','lead_appointments','lead_closure_reviews','lead_notifications','lead_audit_logs','lead_receptions','lead_attachments','lead_care_rounds'] loop
  execute format('alter table public.%I set schema private',n);
  execute format('alter table private.%I rename to %I',n,'compat_'||n);
 end loop;
 for f in select p.oid from pg_proc p join pg_namespace ns on ns.oid=p.pronamespace
  where ns.nspname in ('public','private') and p.proname like 'lead_%' and p.prokind='f' loop
  definition:=pg_get_functiondef(f.oid);
  foreach n in array array['leads','lead_assignments','lead_activities','lead_appointments','lead_closure_reviews','lead_notifications','lead_audit_logs','lead_receptions','lead_attachments','lead_care_rounds'] loop
   definition:=replace(definition,'public.'||n,'private.compat_'||n);
  end loop;
  execute definition;
 end loop;
end $$;

create type public.crm_lead_status as enum ('New','Activated','Onboarded','Closed');
create type public.crm_user_role as enum ('admin','intake','leader','telesale','viewer');
create type public.crm_user_status as enum ('active','suspended');
create type public.crm_ticket_status as enum ('New','Open','Solved','Closed');
create type public.crm_contact_outcome as enum ('called','activated','no_answer','unresponsive','overdue','wrong_phone');
create type public.crm_decision as enum ('none','agreed','declined','hungup','interested','considering','refused');
create type public.crm_refuse_reason as enum ('none','no_need','busy','ineligible');
create type public.crm_call_direction as enum ('outbound','inbound');
create type public.crm_appointment_status as enum ('scheduled','waiting','failed','succeeded','cancelled','attended','missed');
create type public.crm_review_result as enum ('eligible','closed','transferred','reviewed','follow_up');
create type public.crm_notification_type as enum ('reminder','digest','other');

create table public.groups (
 group_id bigint generated by default as identity primary key,
 legacy_id text not null unique, name text not null
);
create table public.users (
 user_id bigint primary key references public.sales(id),
 auth_user_id uuid not null unique references auth.users(id),
 name text not null, email text not null unique,
 role public.crm_user_role not null, group_id bigint not null references public.groups(group_id),
 status public.crm_user_status not null,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
comment on table public.users is 'Mật khẩu do Supabase Auth quản lý; không lưu mật khẩu trong bảng nghiệp vụ.';
create table public.vehicles(vehicle_id bigint generated always as identity primary key,type text not null unique);
create table public.cities(city_id bigint generated always as identity primary key,name text not null unique);
create table public.leads (
 lead_id bigint generated always as identity primary key, legacy_id text not null unique,
 name text not null,phone text not null unique,
 vehicle_id bigint not null references public.vehicles(vehicle_id),
 source text not null references public.lead_sources(id),city_id bigint not null references public.cities(city_id),
 created_at timestamptz,updated_at timestamptz,
 status public.crm_lead_status not null,note text,
 activated_at timestamptz,onboarded_at timestamptz,first_order_id text,
 archived boolean not null default false,version integer not null default 1,
 check(phone ~ '^0[0-9]{9}$')
);
create table public.leads_profile_update (
 lead_profile_update_id bigint generated always as identity primary key,
 lead_id bigint not null references public.leads(lead_id), updated_at timestamptz not null default now(),
 user_id bigint references public.users(user_id),legacy_audit_id text unique,action text not null
);
create table public.leads_profile_update_note (
 lead_profile_update_note_id bigint generated always as identity primary key,
 lead_profile_update_id bigint not null references public.leads_profile_update(lead_profile_update_id),
 note_content text not null
);
create table public.leads_profile_update_status (
 lead_profile_update_status_id bigint generated always as identity primary key,
 lead_profile_update_id bigint not null references public.leads_profile_update(lead_profile_update_id),
 old_status public.crm_lead_status,new_status public.crm_lead_status not null
);
create table public.leads_profile_update_detail (
 lead_profile_update_detail_id bigint generated always as identity primary key,
 lead_profile_update_id bigint not null references public.leads_profile_update(lead_profile_update_id),
 field_name text not null,old_value text,new_value text
);
create table public.notifications (
 id bigint generated always as identity primary key,legacy_id text not null unique,
 user_id bigint not null references public.users(user_id),entity_id text,title text,message text,
 type public.crm_notification_type not null default 'other',read boolean not null default false,
 entity_type text,created_at timestamptz,updated_at timestamptz,read_at timestamptz
);
create table public.lead_assignment_tickets (
 lead_assignment_tickets_id bigint generated always as identity primary key,legacy_id text not null unique,
 lead_id bigint not null references public.leads(lead_id),assigned_by bigint references public.users(user_id),
 assigned_to bigint not null references public.users(user_id),due_date timestamptz not null,
 status public.crm_ticket_status not null,group_id bigint not null references public.groups(group_id),
 created_at timestamptz,updated_at timestamptz,accepted_at timestamptz,close_reason text,
 round integer not null default 1,version integer not null default 1
);
create unique index crm_one_live_ticket on public.lead_assignment_tickets(lead_id) where status<>'Closed';
create table public.lead_assignment_ticket_calls (
 lead_assignment_ticket_calls_id bigint generated always as identity primary key,legacy_id text not null unique,
 lead_assignment_tickets_id bigint not null references public.lead_assignment_tickets(lead_assignment_tickets_id),
 call_direction public.crm_call_direction,
 call_duration_minutes integer,call_duration_seconds integer,call_time timestamptz not null,
 call_status public.crm_contact_outcome not null,decision public.crm_decision not null,
 refuse_reason public.crm_refuse_reason,decision_time timestamptz,decision_place text,note text not null,
 ticket_status public.crm_ticket_status,actor_id bigint references public.users(user_id),round integer,
 voided_at timestamptz,void_reason text,
 check(call_duration_minutes>=0),check(call_duration_seconds>=0)
);
create table public.lead_assignment_ticket_inbox (
 lead_assignment_ticket_inbox_id bigint generated always as identity primary key,legacy_id text not null unique,
 lead_assignment_tickets_id bigint not null references public.lead_assignment_tickets(lead_assignment_tickets_id),
 inbox_time timestamptz not null,inbox_status public.crm_contact_outcome not null,
 decision public.crm_decision not null,refuse_reason public.crm_refuse_reason,
 decision_time timestamptz,decision_place text,note text not null,
 ticket_status public.crm_ticket_status,actor_id bigint references public.users(user_id),round integer,
 voided_at timestamptz,void_reason text
);
create table public.appointment_registration_history (
 appointment_registration_history_id bigint generated always as identity primary key,legacy_id text not null unique,
 lead_assignment_tickets_id bigint not null references public.lead_assignment_tickets(lead_assignment_tickets_id),
 decision_time timestamptz,decision_place text,appointment_registration_status public.crm_appointment_status not null,
 created_at timestamptz,result_at timestamptz,result_cutoff timestamptz,result_reason text,
 previous_legacy_id text,actor_id bigint references public.users(user_id)
);
create table public.lead_closed_ticket_reviews (
 closed_ticket_review_id bigint generated always as identity primary key,legacy_id text not null unique,
 lead_assignment_tickets_id bigint not null unique references public.lead_assignment_tickets(lead_assignment_tickets_id),
 review_result public.crm_review_result,review_basis text,reviewed_by bigint references public.users(user_id),
 reviewed_at timestamptz,created_at timestamptz,close_reason text,version integer not null default 1,
 check(reviewed_at is null or review_result is not null)
);

-- Restrict all table writes to the existing RPCs. No anonymous reads.
-- Policies retain the role and row scope of the existing application.
do $$ declare n text; begin
 foreach n in array array['groups','users','vehicles','cities','leads','leads_profile_update','leads_profile_update_note','leads_profile_update_status','leads_profile_update_detail','notifications','lead_assignment_tickets','lead_assignment_ticket_calls','lead_assignment_ticket_inbox','appointment_registration_history','lead_closed_ticket_reviews'] loop
  execute format('alter table public.%I enable row level security',n);
  execute format('revoke all on public.%I from public,anon,authenticated',n);
  execute format('grant select on public.%I to authenticated',n);
 end loop;
end $$;
create policy crm_groups_read on public.groups for select to authenticated using(private.lead_actor(false) is not null);
create policy crm_vehicles_read on public.vehicles for select to authenticated using(private.lead_actor(false) is not null);
create policy crm_cities_read on public.cities for select to authenticated using(private.lead_actor(false) is not null);
create policy crm_users_read on public.users for select to authenticated using(private.lead_actor(false)->>'role'='admin' or user_id=(private.lead_actor(false)->>'id')::bigint);
create policy crm_leads_read on public.leads for select to authenticated using(private.lead_can_read(legacy_id));
create policy crm_tickets_read on public.lead_assignment_tickets for select to authenticated using(private.lead_can_ticket(legacy_id));
create policy crm_calls_read on public.lead_assignment_ticket_calls for select to authenticated using(exists(select 1 from public.lead_assignment_tickets t where t.lead_assignment_tickets_id=lead_assignment_ticket_calls.lead_assignment_tickets_id));
create policy crm_inbox_read on public.lead_assignment_ticket_inbox for select to authenticated using(exists(select 1 from public.lead_assignment_tickets t where t.lead_assignment_tickets_id=lead_assignment_ticket_inbox.lead_assignment_tickets_id));
create policy crm_appointments_read on public.appointment_registration_history for select to authenticated using(exists(select 1 from public.lead_assignment_tickets t where t.lead_assignment_tickets_id=appointment_registration_history.lead_assignment_tickets_id));
create policy crm_reviews_read on public.lead_closed_ticket_reviews for select to authenticated using(private.lead_actor(false)->>'role'='intake' or (private.lead_actor(false)->>'role'='leader' and exists(select 1 from public.lead_assignment_tickets t where t.lead_assignment_tickets_id=lead_closed_ticket_reviews.lead_assignment_tickets_id)));
create policy crm_notices_read on public.notifications for select to authenticated using(user_id=(private.lead_actor(false)->>'id')::bigint);
create policy crm_updates_read on public.leads_profile_update for select to authenticated using(exists(select 1 from public.leads l where l.lead_id=leads_profile_update.lead_id));
create policy crm_notes_read on public.leads_profile_update_note for select to authenticated using(exists(select 1 from public.leads_profile_update u where u.lead_profile_update_id=leads_profile_update_note.lead_profile_update_id));
create policy crm_statuses_read on public.leads_profile_update_status for select to authenticated using(exists(select 1 from public.leads_profile_update u where u.lead_profile_update_id=leads_profile_update_status.lead_profile_update_id));
create policy crm_details_read on public.leads_profile_update_detail for select to authenticated using(exists(select 1 from public.leads_profile_update u where u.lead_profile_update_id=leads_profile_update_detail.lead_profile_update_id));

create or replace function private.crm_sync_record(resource text,r jsonb,old_row jsonb default null) returns void
language plpgsql security definer set search_path=pg_catalog,public,private as $$
declare d jsonb:=r->'data';item jsonb;lid bigint;hid bigint;actor bigint;key text;
begin
if resource='lead_teams' then
insert into public.groups(legacy_id,name) values(r->>'id',r->>'name') on conflict(legacy_id) do update set name=excluded.name;

elsif resource='sales' then
insert into public.users(user_id,auth_user_id,name,email,role,group_id,status,updated_at) values((r->>'id')::bigint,(r->>'user_id')::uuid,btrim((r->>'first_name')||' '||(r->>'last_name')),r->>'email',coalesce((select role_code from public.lead_user_roles where sales_id=(r->>'id')::bigint),'viewer')::public.crm_user_role,(select group_id from public.groups where legacy_id=coalesce((select team_id from public.lead_user_roles where sales_id=(r->>'id')::bigint),'default')),(case when (r->>'disabled')::boolean then 'suspended' else 'active' end)::public.crm_user_status,now()) on conflict(user_id) do update set auth_user_id=excluded.auth_user_id,name=excluded.name,email=excluded.email,role=excluded.role,group_id=excluded.group_id,status=excluded.status,updated_at=excluded.updated_at;

elsif resource='lead_user_roles' then
select to_jsonb(s) into item from public.sales s where s.id=(r->>'sales_id')::bigint; perform private.crm_sync_record('sales',item,null);
elsif resource='leads' then

insert into public.vehicles(type) values(d->>'vehicle') on conflict do nothing;
insert into public.cities(name) values(d->>'city') on conflict do nothing;
insert into public.leads(legacy_id,name,phone,vehicle_id,source,city_id,created_at,updated_at,status,note,activated_at,onboarded_at,first_order_id,archived,version) values(d->>'id',d->>'name',d->>'phone',(select vehicle_id from public.vehicles where type=d->>'vehicle'),d->>'sourceId',(select city_id from public.cities where name=d->>'city'),(d->>'receivedAt')::timestamptz,(d->>'updatedAt')::timestamptz,(d->>'status')::public.crm_lead_status,d->>'note',(d->>'activatedAt')::timestamptz,(d->>'onboardedAt')::timestamptz,d->>'firstOrderId',(d->>'archived')::boolean,coalesce((d->>'version')::int,1)) on conflict(legacy_id) do update set name=excluded.name,phone=excluded.phone,vehicle_id=excluded.vehicle_id,source=excluded.source,city_id=excluded.city_id,created_at=excluded.created_at,updated_at=excluded.updated_at,status=excluded.status,note=excluded.note,activated_at=excluded.activated_at,onboarded_at=excluded.onboarded_at,first_order_id=excluded.first_order_id,archived=excluded.archived,version=excluded.version;

if old_row is not null and (old_row->'data') is distinct from d then
 select lead_id into lid from public.leads where legacy_id=d->>'id';
 select user_id into actor from public.users where auth_user_id=auth.uid();
 insert into public.leads_profile_update(lead_id,updated_at,user_id,action)
 values(lid,coalesce((d->>'updatedAt')::timestamptz,now()),actor,'update') returning lead_profile_update_id into hid;
 if (old_row->'data'->>'note') is distinct from (d->>'note') then
  insert into public.leads_profile_update_note(lead_profile_update_id,note_content) values(hid,coalesce(d->>'note',''));
 end if;
 if (old_row->'data'->>'status') is distinct from (d->>'status') then
  insert into public.leads_profile_update_status(lead_profile_update_id,old_status,new_status)
  values(hid,(old_row->'data'->>'status')::public.crm_lead_status,(d->>'status')::public.crm_lead_status);
 end if;
 for key in select jsonb_object_keys(d||old_row->'data') loop
  if key not in ('status','note','updatedAt','version') and (old_row->'data'->key) is distinct from (d->key) then
   insert into public.leads_profile_update_detail(lead_profile_update_id,field_name,old_value,new_value)
   values(hid,key,old_row->'data'->key,d->key);
  end if;
 end loop;
end if;

elsif resource='lead_assignments' then
insert into public.lead_assignment_tickets(legacy_id,lead_id,assigned_by,assigned_to,due_date,status,group_id,created_at,updated_at,accepted_at,close_reason,round,version) values(d->>'id',(select lead_id from public.leads where legacy_id=d->>'leadId'),(select user_id from public.users where user_id::text=d->>'assignedBy'),(select user_id from public.users where user_id::text=d->>'assigneeId'),(r->>'expires_at')::timestamptz,(d->>'status')::public.crm_ticket_status,(select group_id from public.groups where legacy_id=d->>'teamId'),(d->>'createdAt')::timestamptz,(d->>'updatedAt')::timestamptz,(d->>'acceptedAt')::timestamptz,d->>'closeReason',coalesce((d->>'round')::int,1),coalesce((d->>'version')::int,1)) on conflict(legacy_id) do update set lead_id=excluded.lead_id,assigned_by=excluded.assigned_by,assigned_to=excluded.assigned_to,due_date=excluded.due_date,status=excluded.status,group_id=excluded.group_id,created_at=excluded.created_at,updated_at=excluded.updated_at,accepted_at=excluded.accepted_at,close_reason=excluded.close_reason,round=excluded.round,version=excluded.version;

elsif resource='lead_activities' then
if d->>'channel'='zalo' then
insert into public.lead_assignment_ticket_inbox(legacy_id,lead_assignment_tickets_id,decision,refuse_reason,note,actor_id,round,voided_at,void_reason,inbox_time,inbox_status) values(d->>'id',(select lead_assignment_tickets_id from public.lead_assignment_tickets where legacy_id=d->>'assignmentId'),(d->>'decision')::public.crm_decision,(d->>'reason')::public.crm_refuse_reason,coalesce(d->>'note',''),(select user_id from public.users where user_id::text=d->>'actorId'),(d->>'round')::int,(d->>'voidedAt')::timestamptz,d->>'voidReason',(d->>'at')::timestamptz,(d->>'outcome')::public.crm_contact_outcome) on conflict(legacy_id) do update set lead_assignment_tickets_id=excluded.lead_assignment_tickets_id,decision=excluded.decision,refuse_reason=excluded.refuse_reason,note=excluded.note,actor_id=excluded.actor_id,round=excluded.round,voided_at=excluded.voided_at,void_reason=excluded.void_reason,inbox_time=excluded.inbox_time,inbox_status=excluded.inbox_status;

else
insert into public.lead_assignment_ticket_calls(legacy_id,lead_assignment_tickets_id,decision,refuse_reason,note,actor_id,round,voided_at,void_reason,call_time,call_status,call_direction,call_duration_minutes,call_duration_seconds) values(d->>'id',(select lead_assignment_tickets_id from public.lead_assignment_tickets where legacy_id=d->>'assignmentId'),(d->>'decision')::public.crm_decision,(d->>'reason')::public.crm_refuse_reason,coalesce(d->>'note',''),(select user_id from public.users where user_id::text=d->>'actorId'),(d->>'round')::int,(d->>'voidedAt')::timestamptz,d->>'voidReason',(d->>'at')::timestamptz,(d->>'outcome')::public.crm_contact_outcome,(d->>'direction')::public.crm_call_direction,(d->>'durationSeconds')::int/60,(d->>'durationSeconds')::int%60) on conflict(legacy_id) do update set lead_assignment_tickets_id=excluded.lead_assignment_tickets_id,decision=excluded.decision,refuse_reason=excluded.refuse_reason,note=excluded.note,actor_id=excluded.actor_id,round=excluded.round,voided_at=excluded.voided_at,void_reason=excluded.void_reason,call_time=excluded.call_time,call_status=excluded.call_status,call_direction=excluded.call_direction,call_duration_minutes=excluded.call_duration_minutes,call_duration_seconds=excluded.call_duration_seconds;

end if;
elsif resource='lead_appointments' then
insert into public.appointment_registration_history(legacy_id,lead_assignment_tickets_id,decision_time,decision_place,appointment_registration_status,created_at,result_at,result_cutoff,result_reason,previous_legacy_id,actor_id) values(d->>'id',(select lead_assignment_tickets_id from public.lead_assignment_tickets where legacy_id=d->>'assignmentId'),(r->>'due_at')::timestamptz,d->>'place',(d->>'status')::public.crm_appointment_status,(d->>'createdAt')::timestamptz,(d->>'resultAt')::timestamptz,(d->>'resultCutoff')::timestamptz,d->>'resultReason',d->>'previousId',(select user_id from public.users where user_id::text=d->>'actorId')) on conflict(legacy_id) do update set lead_assignment_tickets_id=excluded.lead_assignment_tickets_id,decision_time=excluded.decision_time,decision_place=excluded.decision_place,appointment_registration_status=excluded.appointment_registration_status,created_at=excluded.created_at,result_at=excluded.result_at,result_cutoff=excluded.result_cutoff,result_reason=excluded.result_reason,previous_legacy_id=excluded.previous_legacy_id,actor_id=excluded.actor_id;

update public.lead_assignment_ticket_calls set decision_time=(r->>'due_at')::timestamptz,decision_place=d->>'place' where legacy_id=d->>'activityId';
update public.lead_assignment_ticket_inbox set decision_time=(r->>'due_at')::timestamptz,decision_place=d->>'place' where legacy_id=d->>'activityId';

elsif resource='lead_closure_reviews' then
insert into public.lead_closed_ticket_reviews(legacy_id,lead_assignment_tickets_id,review_result,review_basis,reviewed_by,reviewed_at,created_at,close_reason,version) values(d->>'id',(select lead_assignment_tickets_id from public.lead_assignment_tickets where legacy_id=d->>'assignmentId'),(d->>'result')::public.crm_review_result,d->>'note',(select user_id from public.users where user_id::text=d->>'reviewedBy'),(d->>'reviewedAt')::timestamptz,(d->>'at')::timestamptz,d->>'reason',coalesce((d->>'version')::int,1)) on conflict(legacy_id) do update set lead_assignment_tickets_id=excluded.lead_assignment_tickets_id,review_result=excluded.review_result,review_basis=excluded.review_basis,reviewed_by=excluded.reviewed_by,reviewed_at=excluded.reviewed_at,created_at=excluded.created_at,close_reason=excluded.close_reason,version=excluded.version;

elsif resource='lead_notifications' then
insert into public.notifications(legacy_id,user_id,entity_id,title,message,type,read,entity_type,created_at,updated_at,read_at) values(d->>'id',(select user_id from public.users where user_id::text=d->>'recipientId'),coalesce(d->>'appointmentId',d->>'leadId',d->>'target'),d->>'title',d->>'message',(case when d->>'id' like 'reminder-%' then 'reminder' when d->>'id' like 'digest-%' then 'digest' else 'other' end)::public.crm_notification_type,d ? 'readAt',case when d ? 'appointmentId' then 'appointment' when d ? 'leadId' then 'lead' else null end,(d->>'at')::timestamptz,coalesce((d->>'readAt')::timestamptz,(d->>'at')::timestamptz),(d->>'readAt')::timestamptz) on conflict(legacy_id) do update set user_id=excluded.user_id,entity_id=excluded.entity_id,title=excluded.title,message=excluded.message,type=excluded.type,read=excluded.read,entity_type=excluded.entity_type,created_at=excluded.created_at,updated_at=excluded.updated_at,read_at=excluded.read_at;

end if;
end $$;
revoke all on function private.crm_sync_record(text,jsonb,jsonb) from public,anon,authenticated;

create function private.crm_sync_trigger() returns trigger language plpgsql security definer set search_path=pg_catalog,public,private as $$
begin
 if TG_OP='DELETE' then raise exception 'Use application archive commands to preserve migration history'; end if;
 perform private.crm_sync_record(TG_ARGV[0],to_jsonb(new),case when TG_OP='UPDATE' then to_jsonb(old) else null end);
 return new;
end $$;
revoke all on function private.crm_sync_trigger() from public,anon,authenticated;
-- Backfill in foreign-key order. No fabricated actor, time or historical old values.
do $$ declare resource text;schema_name text;table_name text;item jsonb; begin
 foreach resource in array array['lead_teams','sales','leads','lead_assignments','lead_activities','lead_appointments','lead_closure_reviews','lead_notifications'] loop
  schema_name:=case when resource in ('lead_teams','sales') then 'public' else 'private' end;
  table_name:=case when schema_name='private' then 'compat_'||resource else resource end;
  for item in execute format('select to_jsonb(t) from %I.%I t order by to_jsonb(t)::text',schema_name,table_name) loop
   perform private.crm_sync_record(resource,item,null);
  end loop;
 end loop;
 -- Recover factual historical events from audit without inventing missing before states.
 insert into public.leads_profile_update(lead_id,updated_at,user_id,legacy_audit_id,action)
 select l.lead_id,(a.data->>'at')::timestamptz,u.user_id,a.id,coalesce(a.data->>'action','legacy')
 from private.compat_lead_audit_logs a join public.leads l on l.legacy_id=a.lead_id
 left join public.users u on u.user_id::text=a.data->>'actorId'
 where a.data ? 'at' order by a.id;
 foreach resource in array array['lead_teams','sales','lead_user_roles','leads','lead_assignments','lead_activities','lead_appointments','lead_closure_reviews','lead_notifications'] loop
  schema_name:=case when resource in ('lead_teams','sales','lead_user_roles') then 'public' else 'private' end;
  table_name:=case when schema_name='private' then 'compat_'||resource else resource end;
  execute format('create trigger crm_normalize after insert or update or delete on %I.%I for each row execute function private.crm_sync_trigger(%L)',schema_name,table_name,resource);
 end loop;
end $$;
comment on table public.leads is 'Cấu trúc quan hệ theo tài liệu. legacy_id giữ nguyên mã API; ghi nghiệp vụ qua lead_command để áp dụng phân quyền, lịch sử và đồng bộ tương thích.';
comment on column public.leads.created_at is 'Giữ nguyên receivedAt; NULL nếu dữ liệu cũ không có thời điểm tiếp nhận.';
comment on column public.lead_assignment_ticket_calls.call_direction is 'NULL nếu dữ liệu cũ không xác định chiều gọi.';
comment on column public.lead_assignment_ticket_calls.ticket_status is 'NULL nếu dữ liệu cũ không ghi trạng thái phiếu tại thời điểm liên hệ.';
comment on table public.lead_closed_ticket_reviews is 'Kết quả, căn cứ và thời điểm hoàn tất được để NULL khi bàn giao chưa rà soát.';
